uses = {"a": 2, "b": 1, "c": 3}
order = ["a", "b", "a", "c", "b", "c", "c"]
live = set()
for v in order:
    live.add(v)
    uses[v] -= 1
    if uses[v] == 0:
        live.discard(v)
        print("freed", v, "-> live now:", sorted(live))
